def reverse_words(s):
    words = s.split()
    reversed_words = words[::-1]
    return ' '.join(reversed_words)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, reverse_words("Hello World Python"), "Python World Hello")
    check(2, reverse_words("I am a programmer"), "programmer a am I")
    check(3, reverse_words("This is an example"), "example an is This")

def prime_num(n):
    """প্রদত্ত পূর্ণসংখ্যাটি একটি মৌলিক সংখ্যা কিনা তা পরীক্ষা করার জন্য একটি ফাংশন লিখুন।"""
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, prime_num(2), True)
    check(2, prime_num(1), False)
    check(3, prime_num(9), False)
    check(4, prime_num(13), True)
    check(5, prime_num(15), False)
    check(6, prime_num(17), True)
